def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    from collections import Counter
    counts = Counter(cell for row in grid for cell in row)
    bg_color = max(counts, key=counts.get)

    if len(counts) == 1:
        return grid

    # Get all non-bg pixels grouped by color
    color_pixels = {}  # color -> list of (r, c)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_color:
                if grid[r][c] not in color_pixels:
                    color_pixels[grid[r][c]] = []
                color_pixels[grid[r][c]].append((r, c))

    output = [list(row) for row in grid]

    for color, pixels in color_pixels.items():
        # Find bounding box for this color
        row_coords = [p[0] for p in pixels]
        col_coords = [p[1] for p in pixels]

        # Use center of the pattern as reflection axis
        axis_r = sum(row_coords) / len(row_coords)
        axis_c = sum(col_coords) / len(col_coords)

        for r, c in pixels:
            # Reflect the pixel
            reflected_r = round(2 * axis_r - r)
            reflected_c = round(2 * axis_c - c)

            if 0 <= reflected_r < rows and 0 <= reflected_c < cols:
                if output[reflected_r][reflected_c] == bg_color:
                    output[reflected_r][reflected_c] = color

    return output
